sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    var STATE       = 'x_2215689_ai_inc_0_u_ai_processing_state';
    var REVIEW      = 'x_2215689_ai_inc_0_human_review_required';
    var RETRY_COUNT = 'x_2215689_ai_inc_0_ai_retry_count';
    var MAX_RETRIES = 'x_2215689_ai_inc_0_ai_max_retries';
    var RETRY_AT    = 'x_2215689_ai_inc_0_ai_retry_time_out';

    if (current[STATE].changesTo('failed')) {
        var reviewRequired = current.getValue(REVIEW) === '1' || current.getValue(REVIEW) === true;
        if (reviewRequired) {
            current.setValue(STATE, 'awaiting_approval');
            current.setValue(RETRY_AT, '');
            return;
        }

        var retryCount = parseInt(current.getValue(RETRY_COUNT) || 0, 10);
        var maxRetries = parseInt(current.getValue(MAX_RETRIES) || 3, 10);

        if (retryCount >= maxRetries) {
            current.setValue(RETRY_AT, '');
            return;
        }

        var retryTime = new GlideDateTime();
        retryTime.addMinutes(15);

        current.setValue(RETRY_AT, retryTime.getValue());
        current.setValue(STATE, 'waiting_for_retry');
    }
})(current, previous);
